window.POETRY_REGISTER("v5-extra-12-9-0-fb2a73074c20.js",{"poems":[[52301,2],[52349,2],[53144,2],[53192,2],[56708,2],[109552,7],[116979,7],[147804,7],[185585,7],[234162,7],[272079,7],[288132,7],[288519,7],[340214,9],[351005,9],[368169,10],[410104,8],[434068,8],[442436,8],[442638,8],[488527,8],[488586,8],[549727,8],[551956,8],[581857,8],[621481,8],[650074,5],[674392,5],[681569,5],[739686,20]],"pairs":[["朝议大夫高平郡别驾权澈词","钱塘县尉瑯琊王纾书",0],["至此时相距七年而移守桂州","所谓再为郡牧者是已",1],["岂出于故家遗俗之所传者欤","泰定元年十月十三日",2],["为宪宗朝宰相已经弘靖之孙","河南少尹张嗣庆之子",3],["右杨凝式书神仙起居法八行","臣米友仁鉴定真迹跋",4],["崩腾覆溺兮夫岂河伯之不仁","汗漫千里兮荡然室闾",5],["我方折其匕箸兮覆杯而不尝","以甘易苦兮自以为常",6],["何处是月笼松顶兮鹤梦初醒","雪覆芦花兮鹭寒不睡",7],["而负一千五百人善知识之地","而于法道大成也宜矣",8],["难倍伊蓰周兮又奚著而奚作","青山白莲兮辽辽邈邈",9],["而未必徒以诧记事备言之述","不然则亦焉用是物也",10],["吁嗟乎实斋兮有前修之风度","瑟瑟僩僩兮凝然寒素",11],["擎起百一十城世界如一荷叶","此未入母胎已前神通",12],["不屑屑责报归来燕坐高槐轩","艺精时犹闭户究难素",13],["二子喜之皆赠以所制之诗书","诗如于阗𫞩玉装剑璏",14],["嗟你华山人不归来兮徒留连","人间尘士那可以久住",15],["只一声魈肝鬼胆不知在何处","世上亦有奸人立不住",16],["我所思兮商颜之峰首阳之岑","烟霞明灭澒洞不可极",17],["回念昔者之欢会兮今焉别离","爱而不见兮使我踌躇",18],["但见琪花瑶草不可以名状兮","上有好鸟宛宛声和鸣",19],["噫嚱吁夫君兮胡陨魄于斯阿","亲昵何在兮环视维他",20],["又不闻子舆痛辟许公学神农","均为有田方寸欲耕者",21],["似波涛运海翻千万里之鲲鹏","风淜滂飘拂其缘阿兮",22],["遂使君子小人交相美其文墨","尔来文妖墨祟皆绝奇",23],["名山名水相望其间罕与之齐","龙泉乃在山水最佳处",24],["只一声魈肝鬼胆不知在何处","世上亦有奸人立不住",25],["须知道不时行的文章谁家瞧","陕西的秦家得了风水",26],["那刘邦是一个龙胎自然不糙","一杯羹说的好风凉话",26],["果是梅精不二山合离风雨会","四百馀峰奇景难具搜",27],["无良无猛无蠢无灵胥目曰牲","园吏按册皆可呼其名",28],["又不见昌黎先生屈曲自世闲","况非出尘风骨羽化难",29]]});
